<?php
// api/mewa.php
require_once 'config.php';
requireAuth();
requireRole(['mewa', 'admin']);

$action = $_GET['action'] ?? '';

if ($_SERVER['REQUEST_METHOD'] === 'GET') {
    switch ($action) {
            case 'farmers':
                        listFarmers();
                                    break;
                                            case 'forecast_summary':
                                                        forecastSummary();
                                                                    break;
                                                                            case 'crops':
                                                                                        listCrops(); // same as farmer's crop list
                                                                                                    break;
                                                                                                            default:
                                                                                                                        sendJSON(['status' => 'error', 'message' => 'Invalid action'], 400);
                                                                                                                            }
                                                                                                                            } elseif ($_SERVER['REQUEST_METHOD'] === 'POST') {
                                                                                                                                switch ($action) {
                                                                                                                                        case 'register_farmer':
                                                                                                                                                    registerFarmer();
                                                                                                                                                                break;
                                                                                                                                                                        case 'run_analysis':
                                                                                                                                                                                    runAnalysis();
                                                                                                                                                                                                break;
                                                                                                                                                                                                        case 'create_recommendation':
                                                                                                                                                                                                                    createRecommendation();
                                                                                                                                                                                                                                break;
                                                                                                                                                                                                                                        case 'create_region_recommendation':
                                                                                                                                                                                                                                                    createRegionRecommendation();
                                                                                                                                                                                                                                                                break;
                                                                                                                                                                                                                                                                        default:
                                                                                                                                                                                                                                                                                    sendJSON(['status' => 'error', 'message' => 'Invalid action'], 400);
                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                            sendJSON(['status' => 'error', 'message' => 'Method not allowed'], 405);
                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                            function listFarmers() {
                                                                                                                                                                                                                                                                                                $pdo = getDBConnection();
                                                                                                                                                                                                                                                                                                    $stmt = $pdo->query("
                                                                                                                                                                                                                                                                                                            SELECT u.user_id, u.full_name, u.email, u.phone, f.region, f.farm_size_hectares FROM user u JOIN farmer f ON u.user_id = f.user_id ORDER BY u.full_name ");
                                                                                                                                                                                                                                                                                                                $farmers = $stmt->fetchAll();
                                                                                                                                                                                                                                                                                                                    sendJSON(['status' => 'success', 'farmers' => $farmers]);
                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                    function forecastSummary() {
                                                                                                                                                                                                                                                                                                                        $pdo = getDBConnection();
                                                                                                                                                                                                                                                                                                                            $stmt = $pdo->query("
                                                                                                                                                                                                                                                                                                                                    SELECT c.crop_id, c.crop_name,
                                                                                                                                                                                                                                                                                                                                            COALESCE(SUM(pf.expected_yield_tons), 0) AS total_forecast FROM crop c LEFT JOIN production_forecast pf ON c.crop_id = pf.crop_id GROUP BY c.crop_id ");
                                                                                                                                                                                                                                                                                                                                                $summary = $stmt->fetchAll();
                                                                                                                                                                                                                                                                                                                                                    sendJSON(['status' => 'success', 'summary' => $summary]);
                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                    function listCrops() {
                                                                                                                                                                                                                                                                                                                                                        $pdo = getDBConnection();
                                                                                                                                                                                                                                                                                                                                                            $stmt = $pdo->query("SELECT crop_id, crop_name FROM crop ORDER BY crop_name");
                                                                                                                                                                                                                                                                                                                                                                $crops = $stmt->fetchAll();
                                                                                                                                                                                                                                                                                                                                                                    sendJSON(['status' => 'success', 'crops' => $crops]);
                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                    function registerFarmer() {
                                                                                                                                                                                                                                                                                                                                                                        $data = json_decode(file_get_contents('php://input'), true);
                                                                                                                                                                                                                                                                                                                                                                            $username = trim($data['username'] ?? '');
                                                                                                                                                                                                                                                                                                                                                                                $password = $data['password'] ?? '';
                                                                                                                                                                                                                                                                                                                                                                                    $full_name = trim($data['full_name'] ?? '');
                                                                                                                                                                                                                                                                                                                                                                                        $email = trim($data['email'] ?? '');
                                                                                                                                                                                                                                                                                                                                                                                            $phone = trim($data['phone'] ?? '');
                                                                                                                                                                                                                                                                                                                                                                                                $region = trim($data['region'] ?? '');
                                                                                                                                                                                                                                                                                                                                                                                                    $farm_size = floatval($data['farm_size_hectares'] ?? 0);

                                                                                                                                                                                                                                                                                                                                                                                                        if (!$username || !$password || !$full_name || !$email || !$region || !$farm_size) {
                                                                                                                                                                                                                                                                                                                                                                                                                sendJSON(['status' => 'error', 'message' => 'All fields required'], 400);
                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                        $hash = password_hash($password, PASSWORD_DEFAULT);
                                                                                                                                                                                                                                                                                                                                                                                                                            $pdo = getDBConnection();
                                                                                                                                                                                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                                                                                                                                                                                        $pdo->beginTransaction();
                                                                                                                                                                                                                                                                                                                                                                                                                                                $stmt = $pdo->prepare("INSERT INTO user (username, password, full_name, email, phone, role) VALUES (?, ?, ?, ?, ?, 'farmer')");
                                                                                                                                                                                                                                                                                                                                                                                                                                                        $stmt->execute([$username, $hash, $full_name, $email, $phone]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                $userId = $pdo->lastInsertId();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $stmt2 = $pdo->prepare("INSERT INTO farmer (user_id, region, farm_size_hectares) VALUES (?, ?, ?)");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $stmt2->execute([$userId, $region, $farm_size]);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $pdo->commit();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                sendJSON(['status' => 'success', 'message' => 'Farmer registered']);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } catch (PDOException $e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $pdo->rollBack();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if ($e->errorInfo[1] == 1062) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                sendJSON(['status' => 'error', 'message' => 'Username or email already exists'], 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                sendJSON(['status' => 'error', 'message' => 'Database error'], 500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function runAnalysis() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $pdo = getDBConnection();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $pdo->beginTransaction();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $stmt = $pdo->query("
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        SELECT DISTINCT c.crop_id, c.crop_name FROM crop c JOIN production_forecast pf ON c.crop_id = pf.crop_id ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $crops = $stmt->fetchAll();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $mewaId = $_SESSION['user_id'];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $count = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        foreach ($crops as $crop) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $check = $pdo->prepare("SELECT 1 FROM recommendation WHERE crop_id = ? AND farmer_id IS NULL");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $check->execute([$crop['crop_id']]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!$check->fetch()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $stmtRec = $pdo->prepare("
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                INSERT INTO recommendation(crop_id, mewa_id, recommendation_text, priority_level, is_active) VALUES(?, ?, ?, 'medium', TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $text = "يوصى بزراعة " . $crop['crop_name'] . " هذا الموسم بناءً على التوقعات.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $stmtRec->execute([$crop['crop_id'], $mewaId, $text]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $count++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $pdo->commit();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    sendJSON(['status' => 'success', 'message' => 'Analysis complete', 'recommendations' => $count]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (PDOException $e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $pdo->rollBack();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        sendJSON(['status' => 'error', 'message' => 'Analysis failed'], 500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function createRecommendation() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $data = json_decode(file_get_contents('php://input'), true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $cropId = $data['crop_id'] ?? 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $farmerId = isset($data['farmer_id']) && $data['farmer_id'] !== '' ? $data['farmer_id'] : null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $text = trim($data['recommendation_text'] ?? '');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $priority = $data['priority_level'] ?? 'medium';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $snapshotId = isset($data['snapshot_id']) && $data['snapshot_id'] !== '' ? $data['snapshot_id'] : null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $mewaId = $_SESSION['user_id'];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!$cropId || !$text) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    sendJSON(['status' => 'error', 'message' => 'Crop and text required'], 400);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $pdo = getDBConnection();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $stmt = $pdo->prepare("
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    INSERT INTO recommendation(crop_id, farmer_id, mewa_id, snapshot_id, recommendation_text, priority_level, is_active) VALUES(?, ?, ?, ?, ?, ?, TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $stmt->execute([$cropId, $farmerId, $mewaId, $snapshotId, $text, $priority]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            sendJSON(['status' => 'success', 'message' => 'Recommendation created']);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } catch (PDOException $e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        sendJSON(['status' => 'error', 'message' => 'Database error'], 500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function createRegionRecommendation() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $data = json_decode(file_get_contents('php://input'), true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $region = trim($data['region'] ?? '');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $cropId = $data['crop_id'] ?? 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $text = trim($data['recommendation_text'] ?? '');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $priority = $data['priority_level'] ?? 'medium';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $snapshotId = isset($data['snapshot_id']) && $data['snapshot_id'] !== '' ? $data['snapshot_id'] : null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $mewaId = $_SESSION['user_id'];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!$region || !$cropId || !$text) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    sendJSON(['status' => 'error', 'message' => 'Region, crop, and text required'], 400);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $pdo = getDBConnection();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $stmt = $pdo->prepare("SELECT user_id FROM farmer WHERE region = ?");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $stmt->execute([$region]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $farmers = $stmt->fetchAll();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (empty($farmers)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            sendJSON(['status' => 'error', 'message' => 'No farmers found in this region'], 404);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $pdo->beginTransaction();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $inserted = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            foreach ($farmers as $farmer) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $stmtIns = $pdo->prepare("
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        INSERT INTO recommendation (crop_id, farmer_id, mewa_id, snapshot_id, recommendation_text, priority_level, is_active)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        VALUES (?, ?, ?, ?, ?, ?, TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $stmtIns->execute([$cropId, $farmer['user_id'], $mewaId, $snapshotId, $text, $priority]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $inserted++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $pdo->commit();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    sendJSON(['status' => 'success', 'message' => "Recommendation sent to $inserted farmers in $region"]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (PDOException $e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $pdo->rollBack();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        sendJSON(['status' => 'error', 'message' => 'Database error: ' . $e->getMessage()], 500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ?>